def get_axioms() -> list:
    # Linking precondition (added directly, not negated): linalg.vector_norm
    # has no identity for ord < 0 or ord == +inf, so it cannot reduce an empty
    # input ("cannot compute the <ord> norm ... dimension is empty and the
    # operation does not have an identity"). Forbid numel()==0 in that regime.
    # When p is absent the order defaults to 2 (finite, >0): always allowed.
    p = OptVar('p', ScalarVar('p.val'))
    self = TensorVar('self')
    pv = p.value
    ord_real = If(pv.is_integral(), ToReal(pv.int_val), pv.real_val)
    bad_ord = Or(pv.is_inf, And(Not(pv.is_inf), Not(pv.is_nan), ord_real < 0))
    return [
        Not(And(self.numel() == IntVal(0), p.present, bad_ord)),
    ]


